func (t *table) addFileIssue(name string, p pos, kind IssueKind) {
	it := issueAt{p: p, fi: FileIssue{File: name, Offset: p.off, Kind: kind}}
	if kind != IssueUnreadable && kind != IssueOversized {
		t.stateIssues = append(t.stateIssues, it)
