}

// trimIssues keeps the maxFileIssuesPerFile smallest issues once s has grown
// to limit entries.
func trimIssues(s []issueAt, limit int) []issueAt {
	if len(s) < limit {
		return s
	}
	slices.SortFunc(s, issueAt.compare)
	return s[:min(len(s), maxFileIssuesPerFile)]
}

